def main():
 out=HERE/'report';out.mkdir(exist_ok=False);f=pd.read_csv(HERE/'financial-analysis-5/summary.csv');curves=pd.read_csv(HERE/'financial-analysis-5/curves.csv');labels={'ALL__S0_base':'全A原方案','SEMI__S1_base':'固定半导体股票池','COMM__S1_base':'固定通信设备股票池','GATE__S0_base':'行业IX硬闸','FIRST__S0_base':'首次资格F1'};colors=['#465363','#008e9a','#d28b28','#a4a8b0','#9c75ba'];fig,axs=plt.subplots(2,1,figsize=(13,8),sharex=True,gridspec_kw={'height_ratios':[2,1]})
 for i,(aid,label) in enumerate(labels.items()):
  g=curves[curves.account.eq(aid)];dt=pd.to_datetime(g.date);axs[0].plot(dt,g.nav/1e4,label=label,color=colors[i],lw=1.6 if i<3 else .9,ls='-' if i<3 else '--');axs[1].plot(dt,g.drawdown*100,color=colors[i],lw=1 if i<3 else .8)
 axs[0].axhline(100,color='#999',ls=':',lw=.8);axs[0].set_ylabel('净值（万元）');axs[0].legend(ncol=3,fontsize=9);axs[0].set_title('同日起各100万元：固定板块与扩大股票池的差距\n2021—2026-10-16，真实股票研究执行，初始单股15%、总新投入90%')
 axs[1].set_ylabel('回撤（%）')
 for a in axs:a.grid(alpha=.15);a.spines[['top','right']].set_visible(False)
 fig.tight_layout();fig.savefig(out/'real-accounts.png',dpi=145);plt.close(fig)
 fixed=pd.read_csv(HERE/'fixed-three-reference/all-seeds.csv');dynamic=pd.read_csv(HERE/'sector-selection-controls/random-priority-benchmarks.csv');fig,ax=plt.subplots(figsize=(10,5));ax.boxplot([fixed.net_return*100,dynamic.net_return*100],tick_labels=['固定3行业＋预算各自保留','动态补入3行业（随机优先）'],showmeans=True);ax.axhline(0,color='#666',lw=.8);ax.set_ylabel('区间收益（%）');ax.set_title('行业指数代理：相同20个随机种子，全部披露\n固定行业与预算隔离的联合对照，非可直接交易组合');ax.grid(axis='y',alpha=.15);fig.tight_layout();fig.savefig(out/'cash-structure.png',dpi=145);plt.close(fig)
 table=f[['account','net_return','max_drawdown','exposure','closed','win_rate']].copy();table.account=table.account.map(labels)
 for k in ['net_return','max_drawdown','exposure','win_rate']:table[k]=table[k].map(lambda x:f'{x:.2%}')
 table.columns=['路径','总收益','最大回撤','平均仓位','闭合交易','胜率'];solo=pd.read_csv(HERE/'fast-diagnostics/summary.csv');solo=solo[['scope','policy','count','mean','median','positive_fraction','median_drawdown']]
 for k in ['mean','median','positive_fraction','median_drawdown']:solo[k]=solo[k].map(lambda x:f'{x:.2%}')
 html=['<h1>为什么扩大股票池后，原策略的优势丢了</h1>','<p class="lead">单标的趋势择时、板块内选股、全市场机会分配是三个不同环节。这轮先拆解差距，再作有限小修；保留全部旧模型与结果。</p>','<div class="note">同2021—2026-10-16、各100万元，固定通信股票池+306.24%、固定半导体+2.14%，全A原方案−60.89%。更大的机会池仍存在可赚钱的原算法路径，组合选择没有把这些机会接进来。</div>','<h2>先做同口径股票账户</h2>',table.to_html(index=False,border=0),'<p>共同起点取自原半导体连续场景；全A重新以100万元起步，不能把2015老账户缩水资金的时间切片冒充同资金对照。固定池最多6股，全A最多3行业各2股，均单股初仓15%、新投入90%；固定行业是定位实验，不代表事先知道哪个板块会赢。</p>','<img src="real-accounts.png">','<h2>原优势在哪，在哪一步丢了</h2>','<ol><li>原半导体ETF连续IX仍+142.81%、回撤26.01%，49笔。原规则逐股独立运行，1709股IX均值+32.00%、中位数0%；E0均值+90.53%、中位数+19.58%。这些是无共享资金的标准化诊断，不是100万元可实施组合。</li><li>939个同股同IX段、同退出时点对照：首次合格时点平均+8.47%，实际入场时点平均−0.17%，207组由早期盈利机会变成迟入后亏损。这是后来被选中样本的配对，不是全池机会期望；全池84700次首次资格事件均值只有+0.60%。</li><li>独立单股IX平均持有约32.77%的时间；全A旧连续段实际仓位约66.20%，新起点全A为70.85%。每次空位马上从大池补进另一热股，改变了等待节奏与机会分布。仓位提高本身不必然亏损，但不能继续用单标的结果替这种组合背书。</li><li>原全A约47%的新持仓买入时行业自身IX已关闭；简单加行业硬闸仍亏87.33%，因为它仍会换到其他热行业，并切掉一部分个股独立行情。F1仅取每IX段首次全资格也亏66.71%。两项不采用。</li></ol>','<h2>板块数量一致的随机基准：定位组合构造</h2>','<img src="cash-structure.png">','<p>固定3行业＋预算隔离：20种子17组盈利，中位收益+31.69%，中位回撤16.47%。动态随机优先补入3行业：20组仅1组盈利，中位−26.59%。原价格RS择强代理−34.93%，策略净值RS代理−51.01%，均未证明比无预测优先序更好。没有挑随机最优。</p>','<p><b>边界：</b>行业指数不能直接交易。这项对照同时改变固定/动态行业序列和现金归属，尚未分离二者贡献；不能把代理正收益称为股票策略已经修好。90行业各自独立运行约79%盈利，说明组合构造层应先验证，而不是直接否定趋势模型。</p>','<h2>真实大赢家参与</h2>','<p>全A新起点：中际旭创1个持仓周期净赚约3.39万元、新易盛3个周期约1.60万元；固定通信池：分别24/23个周期，累计约39.54/56.69万元。固定半导体池买过寒武纪14个周期，累计约7.44万元；全A没有买到。这些是实际资金贡献，不把股票全程涨幅当账户可得收益。</p>','<h2>迁移检查与验证</h2>','<p>旧单标的执行器有跳空破保护点取消买入，全市场执行器缺这一检查。但只发现4个相关持仓、合计约−2300元，不是大亏主因。1786个单次买卖持仓同入退价桥接，中位差约0.054个百分点，无超过10个百分点的大误差。缺陷已记录，未混入本轮候选来改变比较。</p>','<p>快速算子与原单标的全日净值/交易收益核对；5条真实股票路径7000日账独立现金/股份/费用/权益/T+1核对，最大差0元。报价按需生成，先与原预生成报价的十日金融日志/净值精确核对；4组金融计算约251秒，追加F1约168秒。缓存结果复用，不重算1709股模型。</p>','<h2>下一版的有限问题</h2>','<p>先做板块机会与预算绑定：三个子预算分别保留现金与盈亏；股票卖出后资金不自动借给别的热板块；行业新周期、个股新买点、继续持有分别管理。下一次只比较同一行业/个股机会序列下，共享现金与独立预算的差别，再单独研究在线选择/换绑行业。选择器先与固定随机基准及原现金节奏比较，有增量才下沉全市场股票执行。不继续叠温度、宏观或期限过滤来凑结果。</p>','<p>当前结论是定位到了需要重构的机会分配层；在线行业选择和真实股票预算隔离尚未完成，未宣称可采用的新策略。全部为已见历史、当前存续/市值/行业开发口径。</p>','<h2>原始研究与明细</h2>','<div class="links">']
 for p,label in [('CONCLUSION.md','详细结论'),('financial-analysis-5/summary.csv','5组金融结果'),('financial-analysis-5/campaigns.csv','全部真实持仓'),('entry-attribution/same-episode-entry-pairs.csv','同段入场配对'),('first-opportunity/all-first-events.csv','全池首次机会'),('fast-diagnostics/standalone-stock-summary.csv','1709股独立诊断'),('sector-selection-controls/random-priority-benchmarks.csv','20组动态随机'),('fixed-three-reference/all-seeds.csv','20组固定预算'),('financial-analysis-5/accounting.json','独立核账'),('PROTOCOL.md','基础协议'),('F1_PROTOCOL.md','F1追加协议'),('SECTOR_SELECTION_PROTOCOL.md','上层定位协议')]:html.append(f'<a href="../{p}">{label}</a>')
